@register.simple_tag
def icon(name, css_class=''):
    """Render an inline Lucide icon, e.g. {% icon "bell" "sidebar-link-icon" %}."""
    inner = _ICONS.get(name)
    if inner is None:
        return ''
    classes = 'lucide lucide-' + name
    if css_class:
        classes += ' ' + css_class
    return mark_safe(
        '<svg %s aria-hidden="true" class="%s">%s</svg>' % (_DEFAULT_ATTRS, classes, inner)
    )
